// Checks the TypeScript wallet core against reference outputs from Shrike's own Java library (drongo),
// generated by scratchpad/vectorgen/VectorGen.java, and against the 166 cross-implementation vectors that
// ship with drongo for the unified signature hash.

import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { fromHex, toHex } from '../src/core/bytes';
import { NETWORKS, type NetworkName } from '../src/core/network';
import { AccountKey, childPrivateKey, deriveAccount, deriveAccountPrivate } from '../src/core/keys';
import { cormorantDescriptor, normalizeDescriptor, originDescriptor } from '../src/core/descriptor';
import { encodeAddress, outputScript, type ScriptType } from '../src/core/script';
import { parseTx, serializeTx, txid, vsize, type TxOut } from '../src/core/tx';
import { tapLeafHash, unifiedSighash, type UnifiedScriptTypeValue } from '../src/core/sighash';
import { hashTypeFor, inputDigest, signInput } from '../src/core/sign';

const vectors = JSON.parse(readFileSync(new URL('./vectors/drongo-vectors.json', import.meta.url), 'utf8'));

interface WalletVector {
  network: NetworkName;
  mnemonic: string;
  passphrase: string;
  scriptType: ScriptType;
  fingerprint: string;
  derivation: string;
  xpub: string;
  receiveDescriptor: { cormorant: string; cormorantNormalized: string; withOrigin: string };
  changeDescriptor: { cormorant: string; cormorantNormalized: string; withOrigin: string };
  receive: { index: number; address: string; scriptPubKey: string; pubkey: string }[];
  change: { index: number; address: string; scriptPubKey: string; pubkey: string }[];
}

describe('keys, descriptors and addresses match drongo', () => {
  for (const v of vectors.wallets as WalletVector[]) {
    it(`${v.network} ${v.scriptType} ${v.passphrase ? 'with passphrase' : 'no passphrase'}`, () => {
      const net = NETWORKS[v.network];
      const acct = deriveAccount(v.mnemonic, v.passphrase, v.scriptType, net);
      expect(acct.fingerprint).toBe(v.fingerprint);
      expect(acct.derivation).toBe(v.derivation);
      expect(acct.xpub).toBe(v.xpub);

      const src = { scriptType: v.scriptType, ...acct };
      expect(cormorantDescriptor(src, 0)).toBe(v.receiveDescriptor.cormorant);
      expect(cormorantDescriptor(src, 1)).toBe(v.changeDescriptor.cormorant);
      expect(normalizeDescriptor(cormorantDescriptor(src, 0))).toBe(v.receiveDescriptor.cormorantNormalized);
      expect(normalizeDescriptor(cormorantDescriptor(src, 1))).toBe(v.changeDescriptor.cormorantNormalized);
      expect(originDescriptor(src, 0)).toBe(v.receiveDescriptor.withOrigin);
      expect(originDescriptor(src, 1)).toBe(v.changeDescriptor.withOrigin);

      const key = new AccountKey(acct.xpub, net);
      for (const [chain, list] of [[0, v.receive], [1, v.change]] as const) {
        for (const n of list) {
          const pub = key.pubKey(chain, n.index);
          expect(toHex(pub)).toBe(n.pubkey);
          const spk = outputScript(v.scriptType, pub);
          expect(toHex(spk)).toBe(n.scriptPubKey);
          expect(encodeAddress(spk, net)).toBe(n.address);
        }
      }
    });
  }
});

interface SignVector {
  network: NetworkName;
  mnemonic: string;
  passphrase: string;
  scriptType: ScriptType;
  unified: boolean;
  variant: number;
  unsignedTx: string;
  inputs: { prevTx: string; vout: number; value: number; scriptPubKey: string; path: string }[];
  digests: string[];
  signedTx: string;
  txid: string;
  vsize: number;
}

describe('signed transactions match drongo byte for byte', () => {
  for (const v of vectors.signing as SignVector[]) {
    it(`${v.network} ${v.scriptType} ${v.unified ? 'unified 0x21' : 'legacy hash type'} variant ${v.variant} ${v.passphrase ? 'pp' : ''}`, () => {
      const net = NETWORKS[v.network];
      const acct = deriveAccount(v.mnemonic, v.passphrase, v.scriptType, net);
      const { account } = deriveAccountPrivate(v.mnemonic, v.passphrase, acct.derivation, net);
      const tx = parseTx(v.unsignedTx);
      const spent: TxOut[] = v.inputs.map((i) => {
        const prev = parseTx(i.prevTx);
        expect(txid(prev)).toBe(tx.inputs[v.inputs.indexOf(i)].prevout.txid);
        return { value: i.value, script: fromHex(i.scriptPubKey) };
      });
      const hashType = hashTypeFor(v.scriptType, v.unified);
      v.inputs.forEach((inp, idx) => {
        const [, chainStr, indexStr] = inp.path.split('/');
        const chain = Number(chainStr) as 0 | 1;
        const index = Number(indexStr);
        const privKey = childPrivateKey(account, chain, index);
        const pubKey = new AccountKey(acct.xpub, net).pubKey(chain, index);
        expect(toHex(inputDigest(tx, idx, spent, v.scriptType, pubKey, hashType)).toLowerCase()).toBe(v.digests[idx]);
        signInput(tx, idx, spent, { type: v.scriptType, privKey, pubKey }, hashType);
      });
      expect(toHex(serializeTx(tx))).toBe(v.signedTx);
      expect(txid(tx)).toBe(v.txid);
      expect(vsize(tx)).toBe(Math.ceil(v.vsize));
    });
  }
});

describe('unified signature hash matches the 166 reference vectors', () => {
  const rows = JSON.parse(readFileSync(new URL('./vectors/unified_sighash.json', import.meta.url), 'utf8')) as unknown[][];
  const data = rows.slice(1);
  it('has every vector', () => expect(data.length).toBe(166));
  data.forEach((row, i) => {
    const [scriptCode, rawTx, inIdx, hashType, scriptType, spentOutputs, sighash] = row as [string, string, number, number, number, [number, string][], string];
    it(`vector ${i} type ${scriptType} hashType 0x${hashType.toString(16)}`, () => {
      const tx = parseTx(rawTx);
      const spent = spentOutputs.map(([value, script]) => ({ value, script: fromHex(script) }));
      const st = scriptType as UnifiedScriptTypeValue;
      const digest = unifiedSighash(tx, inIdx, spent, {
        scriptType: st,
        scriptCode: st === 0 || st === 1 ? fromHex(scriptCode) : null,
        hashType,
        tapLeafHash: st === 3 ? tapLeafHash(fromHex(scriptCode)) : null,
      });
      expect(toHex(digest)).toBe(sighash);
    });
  });

  it('refuses a hash type without the opt-in bit', () => {
    const [scriptCode, rawTx, inIdx, hashType, scriptType, spentOutputs] = data[0] as [string, string, number, number, number, [number, string][]];
    const tx = parseTx(rawTx);
    const spent = spentOutputs.map(([value, script]) => ({ value, script: fromHex(script) }));
    expect(() => unifiedSighash(tx, inIdx, spent, { scriptType: scriptType as UnifiedScriptTypeValue, scriptCode: fromHex(scriptCode), hashType: hashType & ~0x20 })).toThrow();
  });
});
